where id = #{id} and status = 1 and pay_status = 0

update orders
set status = #{orders.status}
where id = #{orders.id} and status = 4 and order_time < #{deadline}

update orders
set status = #{orders.status}, cancel_reason = #{orders.cancelReason},
    cancel_time = #{orders.cancelTime}
where id = #{orders.id} and status = 1 and pay_status = 0
  and order_time < #{deadline}

